// Package gateway is a client for the Airlock Gateway Configuration REST API.
//
// Types and per-operation methods in gateway.gen.go are generated by
// oapi-codegen from spec/active.json.
//
// The API is session-based and stateful. Typical usage:
//
//	gw, _ := gateway.New("gateway.example.com", apiKey, gateway.WithInsecureSkipVerify())
//	ctx := context.Background()
//	if err := gw.Connect(ctx); err != nil { ... }   // POST /session/create
//	defer gw.Close(ctx)                             // POST /session/terminate
//
//	gw.LoadConfigurationActiveWithResponse(ctx)     // load config into session
//	res, err := gw.GetVirtualHostsWithResponse(ctx, nil)
//
//go:generate go tool oapi-codegen -config oapi-codegen.yaml ../spec/active.json
//go:generate go run ../internal/genversion -spec ../spec/active.json -out version_gen.go
package gateway

import (
	"context"
	"crypto/tls"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"net/http/cookiejar"
	"strconv"
	"strings"
	"time"
)

// Client embeds the generated ClientWithResponses, so every generated
// operation is available on it. The API key is sent as a Bearer header, the
// JSESSIONID cookie replayed from the HTTP client's cookie jar.
//
// Safe for concurrent use once Connect has returned; Connect and Close are
// not safe to call concurrently with other methods.
type Client struct {
	*ClientWithResponses

	logger       *slog.Logger
	versionCheck bool
	version      string
	timeout      time.Duration // bounds Close's detached context
}

// Option configures a Client.
type Option func(*config)

type config struct {
	port         int
	timeout      time.Duration
	skipVerify   bool
	httpClient   *http.Client
	logger       *slog.Logger
	versionCheck bool

	timeoutSet    bool
	skipVerifySet bool
	portSet       bool
}

// WithoutVersionCheck disables the gateway-version comparison performed by
// Connect. Use it when the API key lacks permission for /system/status or
// when deliberately talking to a gateway of a different major release.
func WithoutVersionCheck() Option { return func(c *config) { c.versionCheck = false } }

// WithLogger sets the logger used for non-fatal warnings such as minor
// version skew. Defaults to slog.Default().
func WithLogger(l *slog.Logger) Option { return func(c *config) { c.logger = l } }

// WithPort sets a non-default management port (default 443). Cannot be
// combined with a host that already contains a port.
func WithPort(port int) Option {
	return func(c *config) { c.port = port; c.portSet = true }
}

// WithTimeout sets the per-request timeout (default 30s). Cannot be combined
// with WithCustomHTTPClient; set Timeout on the custom client instead.
func WithTimeout(d time.Duration) Option {
	return func(c *config) { c.timeout = d; c.timeoutSet = true }
}

// WithInsecureSkipVerify disables TLS certificate verification. In production
// prefer WithCustomHTTPClient with a custom RootCAs pool. Cannot be combined
// with WithCustomHTTPClient; configure TLS on the custom client's transport.
func WithInsecureSkipVerify() Option {
	return func(c *config) { c.skipVerify = true; c.skipVerifySet = true }
}

// WithCustomHTTPClient supplies a custom *http.Client; a cookie jar is added
// if it has none. Not WithHTTPClient — the generated ClientOption owns that
// name.
func WithCustomHTTPClient(h *http.Client) Option {
	return func(c *config) { c.httpClient = h }
}

// New creates a Client for the given host. No network calls are
// made until Connect.
func New(host, apiKey string, opts ...Option) (*Client, error) {
	if host == "" {
		return nil, fmt.Errorf("airlock: host must not be empty")
	}
	if apiKey == "" {
		return nil, fmt.Errorf("airlock: apiKey must not be empty")
	}

	cfg := config{port: 443, timeout: 30 * time.Second, versionCheck: true, logger: slog.Default()}
	for _, o := range opts {
		o(&cfg)
	}
	if cfg.httpClient != nil && (cfg.timeoutSet || cfg.skipVerifySet) {
		return nil, fmt.Errorf("airlock: WithTimeout and WithInsecureSkipVerify cannot be combined with WithCustomHTTPClient; configure the custom client directly")
	}

	hc, err := newHTTPClient(&cfg)
	if err != nil {
		return nil, err
	}
	server, err := serverURL(host, cfg.port, cfg.portSet)
	if err != nil {
		return nil, err
	}

	bearer := func(_ context.Context, req *http.Request) error {
		req.Header.Set("Authorization", "Bearer "+apiKey)
		return nil
	}
	c, err := NewClientWithResponses(server, WithHTTPClient(hc), WithRequestEditorFn(bearer))
	if err != nil {
		return nil, fmt.Errorf("airlock: %w", err)
	}
	return &Client{
		ClientWithResponses: c,
		logger:              cfg.logger,
		versionCheck:        cfg.versionCheck,
		timeout:             cfg.timeout,
	}, nil
}

// Connect starts a REST session (POST /session/create). A successful Connect
// must be paired with Close.
//
// If the version check rejects the gateway (*VersionSkewError), the session
// is terminated.
func (c *Client) Connect(ctx context.Context) error {
	res, err := c.CreateSessionWithResponse(ctx)
	if err != nil {
		return fmt.Errorf("airlock: create session: %w", err)
	}
	if err := CheckStatus(res.StatusCode(), res.Body); err != nil {
		var apiErr *APIError
		if errors.As(err, &apiErr) && (apiErr.StatusCode == 401 || apiErr.StatusCode == 403) {
			return fmt.Errorf("create session: %w (check the API key and permissions)", err)
		}
		return fmt.Errorf("create session: %w", err)
	}
	if c.versionCheck {
		if err := c.checkVersion(ctx); err != nil {
			_ = c.Close(ctx)
			return err
		}
	}
	return nil
}

// Close terminates the REST session. Safe to ignore errors in a defer.
//
// Cancellation of ctx is ignored so a deferred Close still reaches the
// gateway after a timeout; ctx's values are kept, and the client's timeout
// (see WithTimeout) bounds the call.
func (c *Client) Close(ctx context.Context) error {
	ctx = context.WithoutCancel(ctx)
	if c.timeout > 0 { // WithTimeout(0) means "no timeout", as for http.Client
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, c.timeout)
		defer cancel()
	}

	res, err := c.TerminateSessionWithResponse(ctx)
	if err != nil {
		return fmt.Errorf("airlock: terminate session: %w", err)
	}
	if err := CheckStatus(res.StatusCode(), res.Body); err != nil {
		return fmt.Errorf("terminate session: %w", err)
	}
	return nil
}

// Version returns the version reported by the connected gateway.
func (c *Client) Version() string { return c.version }

// VersionSkewError is returned by Connect when the gateway runs a different
// major release than GeneratedFromVersion. Minor skew only warns.
type VersionSkewError struct {
	GatewayVersion string // version reported by the gateway
	ClientVersion  string // version the client was generated from
}

func (e *VersionSkewError) Error() string {
	return fmt.Sprintf("airlock: gateway runs %s but this client was generated from the %s specification; regenerate from the gateway's spec or connect with WithoutVersionCheck",
		e.GatewayVersion, e.ClientVersion)
}

// APIError is a JSON:API error response (HTTP 4xx/5xx) from the gateway.
type APIError struct {
	StatusCode int
	Errors     []ErrorData
	Body       string // raw body, for anything the typed fields miss
}

func (e *APIError) Error() string {
	msgs := make([]string, 0, len(e.Errors))
	for _, eo := range e.Errors {
		var parts []string
		if eo.Code != nil {
			parts = append(parts, *eo.Code)
		}
		switch { // a gateway may send title instead of detail
		case eo.Detail != nil:
			parts = append(parts, *eo.Detail)
		case eo.Title != nil:
			parts = append(parts, *eo.Title)
		}
		if len(parts) > 0 {
			msgs = append(msgs, strings.Join(parts, ": "))
		}
	}
	if len(msgs) > 0 {
		return fmt.Sprintf("airlock: HTTP %d (%s)", e.StatusCode, strings.Join(msgs, "; "))
	}
	if body := strings.Join(strings.Fields(e.Body), " "); body != "" {
		return fmt.Sprintf("airlock: HTTP %d (%s)", e.StatusCode, truncate(body, 200))
	}
	return fmt.Sprintf("airlock: HTTP %d", e.StatusCode)
}

func truncate(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	return string(r[:n]) + "…"
}

// CheckStatus converts a non-2xx response into an *APIError, decoding the
// JSON:API errors array from the body when present. Use it with the
// StatusCode and Body of any generated *WithResponse result.
func CheckStatus(status int, body []byte) error {
	if status < 400 {
		return nil
	}
	apiErr := &APIError{StatusCode: status, Body: string(body)}
	var doc ErrorDocument
	if json.Unmarshal(body, &doc) == nil && doc.Errors != nil {
		apiErr.Errors = *doc.Errors
	}
	return apiErr
}

func newHTTPClient(cfg *config) (*http.Client, error) {
	hc := cfg.httpClient
	if hc == nil {
		transport, ok := http.DefaultTransport.(*http.Transport)
		if ok {
			transport = transport.Clone()
		} else { // DefaultTransport replaced by some other RoundTripper
			transport = &http.Transport{Proxy: http.ProxyFromEnvironment}
		}
		if cfg.skipVerify {
			transport.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
		}
		hc = &http.Client{Transport: transport, Timeout: cfg.timeout}
	}
	if hc.Jar == nil {
		jar, err := cookiejar.New(nil)
		if err != nil {
			return nil, fmt.Errorf("airlock: creating cookie jar: %w", err)
		}
		clone := *hc
		clone.Jar = jar
		hc = &clone
	}
	return hc, nil
}

func serverURL(host string, port int, portSet bool) (string, error) {
	if i := strings.Index(host, "://"); i >= 0 {
		hostPort, _, _ := strings.Cut(host[i+3:], "/")
		return "", fmt.Errorf("airlock: host %q must not include a scheme; pass %q instead", host, hostPort)
	}

	hostOnly := host
	if h, p, err := net.SplitHostPort(host); err == nil {
		if portSet {
			return "", fmt.Errorf("airlock: host %q already contains a port; do not combine with WithPort", host)
		}
		hostPort, perr := strconv.Atoi(p)
		if perr != nil {
			return "", fmt.Errorf("airlock: invalid port in host %q", host)
		}
		hostOnly, port = h, hostPort
	}
	// Accept "[::1]" — an IPv6 literal in brackets without a port.
	hostOnly = strings.TrimSuffix(strings.TrimPrefix(hostOnly, "["), "]")

	return fmt.Sprintf("https://%s/airlock/rest", net.JoinHostPort(hostOnly, strconv.Itoa(port))), nil
}

// checkVersion errors on major skew only; everything else warns.
func (c *Client) checkVersion(ctx context.Context) error {
	res, err := c.GetNodeStatusWithResponse(ctx)
	if err != nil {
		c.logger.Warn("airlock: could not determine gateway version", "error", err)
		return nil
	}
	if serr := CheckStatus(res.StatusCode(), res.Body); serr != nil ||
		res.JSON200 == nil || res.JSON200.Data.Attributes == nil {
		c.logger.Warn("airlock: could not determine gateway version",
			"status", res.StatusCode())
		return nil
	}
	gv := res.JSON200.Data.Attributes.Version
	c.version = gv

	gMaj, gMin, ok1 := parseMajorMinor(gv)
	cMaj, cMin, ok2 := parseMajorMinor(GeneratedFromVersion)
	if !ok1 || !ok2 {
		c.logger.Warn("airlock: could not parse versions for skew check",
			"gateway", gv, "client", GeneratedFromVersion)
		return nil
	}
	if gMaj != cMaj {
		return &VersionSkewError{GatewayVersion: gv, ClientVersion: GeneratedFromVersion}
	}
	if gMin != cMin {
		c.logger.Warn("airlock: gateway version differs from the version this client was generated from; new attributes may be missing and removed ones may fail",
			"gateway", gv, "client", GeneratedFromVersion)
	}
	return nil
}

func parseMajorMinor(v string) (major, minor int, ok bool) {
	n, _ := fmt.Sscanf(v, "%d.%d", &major, &minor)
	return major, minor, n == 2
}
